        assert.equal(pin.codeHash,E.keccak256(await c.rpc('eth_getCode',[helper,'latest'])));
        const child=E.getCreateAddress({from:helper,nonce});
        assert.equal(await c.rpc('eth_getCode',[child,'latest']),'0x00'+body.slice(2));
