      }
      return {};
    },{kernelArtifact:selection});
    assert(result.cleanup.stopped&&result.cleanup.cacheRemoved);
  }
  assert.deepEqual(identities[0],identities[1]);assert.deepEqual(identities[1],identities[2]);
});

